1	import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";
2	
3	const SPOTIFY_TOKEN_URL = "https://accounts.spotify.com/api/token";
4	
5	export const COOKIE_NAME = "rt";
6	const COOKIE_MAX_AGE = 30 * 24 * 60 * 60; // 30 days, in seconds
7	
8	const IV_LENGTH = 12;
9	const AUTH_TAG_LENGTH = 16;
10	
11	function getKey() {
12	  const b64 = process.env.COOKIE_ENCRYPTION_KEY;
13	  if (!b64) {
14	    throw new Error("COOKIE_ENCRYPTION_KEY is not set");
15	  }
16	  const key = Buffer.from(b64, "base64");
17	  if (key.length !== 32) {
18	    throw new Error("COOKIE_ENCRYPTION_KEY must decode to 32 bytes");
19	  }
20	  return key;
21	}
22	
23	export function sealToken(plaintext) {
24	  const key = getKey();
25	  const iv = randomBytes(IV_LENGTH);
26	  const cipher = createCipheriv("aes-256-gcm", key, iv);
27	  const ciphertext = Buffer.concat([
28	    cipher.update(plaintext, "utf8"),
29	    cipher.final(),
30	  ]);
31	  const authTag = cipher.getAuthTag();
32	  return Buffer.concat([iv, authTag, ciphertext]).toString("base64url");
33	}
34	
35	export function openToken(sealed) {
36	  const key = getKey();
37	  const data = Buffer.from(sealed, "base64url");
38	  const iv = data.subarray(0, IV_LENGTH);
39	  const authTag = data.subarray(IV_LENGTH, IV_LENGTH + AUTH_TAG_LENGTH);
40	  const ciphertext = data.subarray(IV_LENGTH + AUTH_TAG_LENGTH);
41	  const decipher = createDecipheriv("aes-256-gcm", key, iv);
42	  decipher.setAuthTag(authTag);
43	  return Buffer.concat([
44	    decipher.update(ciphertext),
45	    decipher.final(),
46	  ]).toString("utf8");
47	}
