49	function cookieAttrs(nameValue, maxAge, secure) {
50	  const attrs = [
51	    nameValue,
52	    "HttpOnly",
53	    "SameSite=Lax",
54	    "Path=/",
55	    `Max-Age=${maxAge}`,
56	  ];
57	  if (secure) attrs.push("Secure");
58	  return attrs.join("; ");
59	}
60	
61	export function buildSessionCookie(sealed, { secure }) {
62	  return cookieAttrs(`${COOKIE_NAME}=${sealed}`, COOKIE_MAX_AGE, secure);
63	}
64	
65	export function clearSessionCookie({ secure }) {
66	  return cookieAttrs(`${COOKIE_NAME}=`, 0, secure);
67	}
68	
69	export function parseCookies(header) {
70	  const out = {};
71	  if (!header) return out;
72	  for (const part of header.split(";")) {
73	    const idx = part.indexOf("=");
74	    if (idx === -1) continue;
75	    const name = part.slice(0, idx).trim();
76	    if (!name) continue;
77	    const raw = part.slice(idx + 1).trim();
78	    try {
79	      out[name] = decodeURIComponent(raw);
80	    } catch {
81	      out[name] = raw;
82	    }
83	  }
84	  return out;
85	}
