87	async function postTokenRequest(params, { clientId, clientSecret }) {
88	  const credentials = Buffer.from(`${clientId}:${clientSecret}`).toString(
89	    "base64",
90	  );
91	  return fetch(SPOTIFY_TOKEN_URL, {
92	    method: "POST",
93	    headers: {
94	      Authorization: `Basic ${credentials}`,
95	      "Content-Type": "application/x-www-form-urlencoded",
96	    },
97	    body: new URLSearchParams(params),
98	  });
99	}
100	
101	export async function exchangeRefreshToken(
102	  refreshToken,
103	  { clientId, clientSecret },
104	) {
105	  const response = await postTokenRequest(
106	    { grant_type: "refresh_token", refresh_token: refreshToken },
107	    { clientId, clientSecret },
108	  );
109	
110	  if (!response.ok) {
111	    throw new Error(`REFRESH_FAILED:${response.status}`);
112	  }
113	
114	  const data = await response.json();
115	  return {
116	    accessToken: data.access_token,
117	    expiresIn: data.expires_in,
118	    refreshToken: data.refresh_token ?? refreshToken,
119	  };
120	}
121	
122	export async function exchangeAuthCode(
123	  code,
124	  { clientId, clientSecret, redirectUri },
125	) {
126	  const response = await postTokenRequest(
127	    { grant_type: "authorization_code", code, redirect_uri: redirectUri },
128	    { clientId, clientSecret },
129	  );
130	
131	  if (!response.ok) {
132	    throw new Error(`AUTH_CODE_EXCHANGE_FAILED:${response.status}`);
133	  }
134	
135	  const data = await response.json();
136	  if (!data.refresh_token) {
137	    throw new Error("AUTH_CODE_EXCHANGE_FAILED:no_refresh_token");
138	  }
139	  return { refreshToken: data.refresh_token };
140	}
141	
142	export async function createSession(
143	  code,
144	  { clientId, clientSecret, redirectUri, secure },
145	) {
146	  const { refreshToken } = await exchangeAuthCode(code, {
147	    clientId,
148	    clientSecret,
149	    redirectUri,
150	  });
151	  return { cookie: buildSessionCookie(sealToken(refreshToken), { secure }) };
152	}
153	
154	export async function refreshSession(
155	  sealed,
156	  { clientId, clientSecret, secure },
157	) {
158	  const refreshToken = openToken(sealed); // throws on tamper/invalid
159	  const result = await exchangeRefreshToken(refreshToken, {
160	    clientId,
161	    clientSecret,
162	  });
163	  const rotated = result.refreshToken !== refreshToken;
164	  return {
165	    accessToken: result.accessToken,
166	    expiresIn: result.expiresIn,
167	    cookie: rotated
168	      ? buildSessionCookie(sealToken(result.refreshToken), { secure })
169	      : null,
170	  };
171	}
