3	export default async function handler(req, res) {
4	  const { code, error } = req.query;
5	  const frontendUrl = process.env.FRONTEND_URL;
6	
7	  if (error || !code) {
8	    return res.redirect(`${frontendUrl}?error=access_denied`);
9	  }
10	
11	  try {
12	    const { cookie } = await createSession(code, {
13	      clientId: process.env.VITE_SPOTIFY_CLIENT_ID,
14	      clientSecret: process.env.SPOTIFY_CLIENT_SECRET,
15	      redirectUri: process.env.REDIRECT_URI,
16	      secure: true,
17	    });
18	    res.setHeader("Set-Cookie", cookie);
19	    return res.redirect(frontendUrl);
20	  } catch (err) {
21	    console.error("[api/callback] token exchange failed:", err);
22	    return res.redirect(`${frontendUrl}?error=token_exchange_failed`);
23	  }
24	}
