3	export default async function handler(req, res) {
4	  const sealed = parseCookies(req.headers.cookie)[COOKIE_NAME];
5	  if (!sealed) {
6	    return res.status(401).json({ error: "no_session" });
7	  }
8	
9	  try {
10	    const { accessToken, expiresIn, cookie } = await refreshSession(sealed, {
11	      clientId: process.env.VITE_SPOTIFY_CLIENT_ID,
12	      clientSecret: process.env.SPOTIFY_CLIENT_SECRET,
13	      secure: true,
14	    });
15	    if (cookie) res.setHeader("Set-Cookie", cookie); // persist rotation
16	    return res.status(200).json({
17	      access_token: accessToken,
18	      expires_in: expiresIn,
19	    });
20	  } catch (err) {
21	    console.error("[api/refresh] refresh failed:", err);
22	    return res.status(401).json({ error: "refresh_failed" });
23	  }
24	}
