1	const CLIENT_ID = import.meta.env.VITE_SPOTIFY_CLIENT_ID;
2	if (!CLIENT_ID)
3	  throw new Error("VITE_SPOTIFY_CLIENT_ID is not set — check your .env file");
4	const SCOPE = "user-read-currently-playing user-modify-playback-state";
5	
6	const RATE_LIMITED_DEFAULT = "5";
7	
8	// Non-success Spotify response -> the Error we throw. Returns null for 2xx.
9	// `overrides` adds endpoint-specific status codes (e.g. player controls' 403/404).
10	function spotifyError(response, overrides = {}) {
11	  const byStatus = {
12	    401: () => new Error("TOKEN_EXPIRED"),
13	    429: () =>
14	      new Error(
15	        `RATE_LIMITED:${response.headers.get("Retry-After") ?? RATE_LIMITED_DEFAULT}`,
16	      ),
17	    ...overrides,
18	  };
19	  if (byStatus[response.status]) return byStatus[response.status]();
20	  return response.ok ? null : new Error(`SPOTIFY_ERROR:${response.status}`);
21	}
22	
23	export function buildAuthUrl() {
24	  const redirectUri =
25	    import.meta.env.VITE_REDIRECT_URI ?? "http://127.0.0.1:3000/api/callback";
26	  const params = new URLSearchParams({
27	    client_id: CLIENT_ID,
28	    response_type: "code",
29	    redirect_uri: redirectUri,
30	    scope: SCOPE,
31	  });
32	  return `https://accounts.spotify.com/authorize?${params}`;
33	}
34	
35	export async function fetchCurrentlyPlaying(token) {
36	  const response = await fetch(
37	    "https://api.spotify.com/v1/me/player/currently-playing",
38	    {
39	      headers: { Authorization: `Bearer ${token}` },
40	    },
41	  );
42	
43	  if (response.status === 204) return null;
44	  const err = spotifyError(response);
45	  if (err) throw err;
46	
47	  const data = await response.json();
48	  if (!data.item) return null;
49	
50	  return {
51	    trackName: data.item.name,
52	    artistName: data.item.artists[0]?.name ?? null, // PRIMARY artist — keep, used elsewhere for geo lookup
53	    artistNames: data.item.artists.map((a) => a.name).join(", ") || null, // all artists joined, for display
54	    albumImageUrl: data.item.album.images[0]?.url ?? null,
55	    trackId: data.item.id,
56	    isPlaying: data.is_playing,
57	    progressMs: data.progress_ms,
58	    durationMs: data.item.duration_ms,
59	  };
60	}
