62	async function playerCommand(method, command, token) {
63	  const response = await fetch(
64	    `https://api.spotify.com/v1/me/player/${command}`,
65	    {
66	      method,
67	      headers: { Authorization: `Bearer ${token}` },
68	    },
69	  );
70	  if (response.status === 204) return; // success (no body)
71	  const err = spotifyError(response, {
72	    403: () => new Error("PLAYBACK_UNAVAILABLE"), // non-Premium / restricted
73	    404: () => new Error("NO_ACTIVE_DEVICE"),
74	  });
75	  if (err) throw err;
76	}
