1	import { useCallback, useEffect, useState } from "react";
2	import { logout, refreshAccessToken } from "./auth.js";
3	import LandingPage from "./components/LandingPage.jsx";
4	import LogoutButton from "./components/LogoutButton.jsx";
5	import MapView from "./components/MapView.jsx";
6	import { devLog } from "./devLog.js";
7	
8	export default function App() {
9	  const [token, setToken] = useState(null);
10	  const [error, setError] = useState(null);
11	  const [booting, setBooting] = useState(true);
12	
13	  // Surface an OAuth ?error from the callback redirect, then clean the URL.
14	  useEffect(() => {
15	    const params = new URLSearchParams(window.location.search);
16	    const e = params.get("error");
17	    if (e) {
18	      setError(e);
19	      window.history.replaceState({}, "", "/");
20	    }
21	  }, []);
22	
23	  // Bootstrap: exchange the session cookie for an access token.
24	  useEffect(() => {
25	    let cancelled = false;
26	    devLog("[app] bootstrapping session");
27	    refreshAccessToken()
28	      .then((t) => {
29	        if (cancelled) return;
30	        devLog("[app] session restored");
31	        setToken(t);
32	      })
33	      .catch(() => {
34	        devLog("[app] no active session, showing login");
35	      })
36	      .finally(() => {
37	        if (!cancelled) setBooting(false);
38	      });
39	    return () => {
40	      cancelled = true;
41	    };
42	  }, []);
43	
44	  // A poll hit a 401: try to refresh; only truly log out if that fails.
45	  const handleTokenExpired = useCallback(async () => {
46	    devLog("[app] token expired, refreshing");
47	    try {
48	      const t = await refreshAccessToken();
49	      devLog("[app] token refreshed");
50	      setToken(t);
51	    } catch {
52	      devLog("[app] refresh failed, logging out");
53	      setToken(null);
54	      setError("session_expired");
55	    }
56	  }, []);
57	
58	  const handleLogout = useCallback(async () => {
59	    devLog("[app] logging out");
60	    await logout();
61	    setToken(null);
62	    setError(null);
63	  }, []);
64	
65	  if (booting) return null;
66	
67	  if (token) {
68	    return (
69	      <>
70	        <MapView token={token} onTokenExpired={handleTokenExpired} />
71	        <LogoutButton onLogout={handleLogout} />
72	      </>
73	    );
74	  }
75	
76	  return <LandingPage error={error} />;
77	}
