1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { devLog } from "../devLog.js";
3	import { lookupArtistLocation } from "../geo.js";
4	import { classifyPollError } from "../pollError.js";
5	import { fetchCurrentlyPlaying, pause, play, skipToNext } from "../spotify.js";
6	import LeafletMap from "./LeafletMap.jsx";
7	import NowPlayingCard from "./NowPlayingCard.jsx";
8	
9	const POLL_MS = 5_000;
10	const PACIFIC_FALLBACK = { lat: 0, lng: -160, placeName: "Unknown location" };
11	
12	export default function MapView({ token, onTokenExpired }) {
13	  const [track, setTrack] = useState(null);
14	  const [location, setLocation] = useState(null);
15	  const [status, setStatus] = useState("loading");
16	  const [controlMessage, setControlMessage] = useState(null);
17	  const lastArtistRef = useRef(null);
18	  const refreshingRef = useRef(false);
19	  const mountedRef = useRef(true);
20	
21	  useEffect(() => {
22	    mountedRef.current = true;
23	    return () => {
24	      mountedRef.current = false;
25	    };
26	  }, []);
27	
28	  // Fetch the currently-playing track and update state. Throws on API error so
29	  // callers (the poll loop and the control handlers) can apply their own
30	  // error handling. Both share this so a control action can refresh instantly.
31	  const syncNowPlaying = useCallback(async () => {
32	    const current = await fetchCurrentlyPlaying(token);
33	    if (!mountedRef.current) return;
34	
35	    if (!current) {
36	      devLog("[poll] nothing playing");
37	      setStatus("idle");
38	      return;
39	    }
40	
41	    // update track immediately; location catches up asynchronously
42	    setTrack(current);
43	    setStatus("playing");
44	    devLog(`[poll] now playing: ${current.artistName} – ${current.trackName}`);
45	
46	    if (current.artistName !== lastArtistRef.current) {
47	      lastArtistRef.current = current.artistName;
48	      devLog(`[poll] artist changed, looking up ${current.artistName}`);
49	      const loc = await lookupArtistLocation(current.artistName);
50	      if (mountedRef.current) setLocation(loc ?? PACIFIC_FALLBACK);
51	    }
52	  }, [token]);
53	
54	  // Shared TOKEN_EXPIRED refresh path, guarded so only one refresh runs at a
55	  // time even across overlapping poll/control errors.
56	  const refreshToken = useCallback(async () => {
57	    if (refreshingRef.current) return;
58	    refreshingRef.current = true;
59	    devLog("[poll] token expired, refreshing");
60	    try {
61	      await onTokenExpired();
62	    } finally {
63	      refreshingRef.current = false;
64	    }
65	  }, [onTokenExpired]);
66	
67	  useEffect(() => {
68	    let cancelled = false;
69	
70	    async function poll() {
71	      if (cancelled) return;
72	      try {
73	        await syncNowPlaying();
74	      } catch (err) {
75	        if (cancelled) return;
76	        const action = classifyPollError(err.message);
77	        if (action.type === "refresh") {
78	          await refreshToken();
79	          return;
80	        }
81	        if (action.type === "retry") {
82	          devLog(`[poll] rate limited, retrying in ${action.seconds}s`);
83	          // safe to schedule even near unmount: poll() checks cancelled at the top
84	          setTimeout(poll, action.seconds * 1000);
85	          return;
86	        }
87	        console.error("[poll] error:", err.message);
88	        setStatus("error");
89	      }
90	    }
91	
92	    poll();
93	    const id = setInterval(poll, POLL_MS);
94	    return () => {
95	      cancelled = true;
96	      clearInterval(id);
97	    };
98	  }, [syncNowPlaying, refreshToken]);
99	
100	  async function runControl(action) {
101	    try {
102	      await action();
103	      setControlMessage(null);
104	      return true;
105	    } catch (err) {
106	      if (err.message === "TOKEN_EXPIRED") {
107	        await refreshToken();
108	      } else {
109	        setControlMessage("Playback control not available");
110	      }
111	      return false;
112	    }
113	  }
114	
115	  async function handlePlayPause() {
116	    const wasPlaying = track?.isPlaying;
117	    const ok = await runControl(() =>
118	      wasPlaying ? pause(token) : play(token),
119	    );
120	    if (!ok) return;
121	    // Optimistic flip so the icon updates immediately. We deliberately do NOT
122	    // re-sync here: Spotify's currently-playing read is eventually consistent
123	    // and for a moment still reports the old is_playing, which would clobber
124	    // this flip and make the button flicker back. The 5s poll reconciles.
125	    setTrack((t) => (t ? { ...t, isPlaying: !wasPlaying } : t));
126	  }
127	
128	  async function handleNext() {
129	    const ok = await runControl(() => skipToNext(token));
130	    if (!ok) return;
131	    syncNowPlaying().catch(() => {});
132	  }
133	
134	  if (status === "idle") {
135	    return (
136	      <div
137	        style={{
138	          display: "flex",
139	          alignItems: "center",
140	          justifyContent: "center",
141	          height: "100vh",
142	          fontFamily: "sans-serif",
143	        }}
144	      >
145	        <p>Play something on Spotify</p>
146	      </div>
147	    );
148	  }
149	
150	  if (status === "error") {
151	    return (
152	      <div
153	        style={{
154	          display: "flex",
155	          alignItems: "center",
156	          justifyContent: "center",
157	          height: "100vh",
158	          fontFamily: "sans-serif",
159	        }}
160	      >
161	        <p>Something went wrong. Check the console.</p>
162	      </div>
163	    );
164	  }
165	
166	  // renders for 'loading' (initial) and 'playing' — LeafletMap handles null track/location
167	  return (
168	    <div style={{ position: "relative", height: "100vh", width: "100%" }}>
169	      <LeafletMap track={track} location={location} />
170	      {track && (
171	        <NowPlayingCard
172	          track={track}
173	          placeName={location?.placeName}
174	          onPlayPause={handlePlayPause}
175	          onNext={handleNext}
176	          controlMessage={controlMessage}
177	        />
178	      )}
179	    </div>
180	  );
181	}
